-- SG SEO meta round 2 (2026-10-25): every funded course's meta_description now highlights its funding
-- scheme (WSQ / IBF / CASL) and, where the course carries the badge, SkillsFuture Credit and UTAP
-- (user directive 2026-10-25 for SG funded courses; UTAP outbound-marketing ban does not apply to SG
-- storefront meta). Funding sentence is built from each course's current approved badges; course text
-- shortened where needed to stay <= 160 chars. meta_keyword gains the scheme / SkillsFuture Credit / UTAP
-- phrases where missing. 306 TGS- courses.
--
-- Peer-safe: a row is only replaced while it still holds the exact value migration 1844 wrote, so any
-- later edit (rename / repurpose by another migration, admin edit) is left alone.
-- Also re-applies 1845's meta to category 397, skipped there because its name carries a double space.
--
-- SG-only (store guard) -> no-op on MY/GH. Idempotent. Post-deploy: cache flush + catalog_category_flat reindex.

SET @sg := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
SET @a_mdesc := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_description' AND backend_type = 'varchar');
SET @a_mkey  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_keyword' AND backend_type = 'text');
SET @c_name   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'name');
SET @c_mtitle := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_title' AND backend_type = 'varchar');
SET @c_mdesc  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_description' AND backend_type = 'text');
SET @c_mkey   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_keywords' AND backend_type = 'text');
SET @ok := (@sg = 1 AND @a_mdesc IS NOT NULL AND @a_mkey IS NOT NULL AND @c_mtitle IS NOT NULL);

DROP TABLE IF EXISTS mms_seo_r2_stage;

CREATE TABLE mms_seo_r2_stage (
  sku    VARCHAR(64) NOT NULL PRIMARY KEY,
  old_md VARCHAR(255) NOT NULL,
  md     VARCHAR(255) NOT NULL,
  old_mk TEXT NOT NULL,
  mk     TEXT NOT NULL
) DEFAULT CHARSET = utf8;


UPDATE catalog_product_entity_varchar v
  JOIN catalog_product_entity e ON e.entity_id = v.entity_id
  JOIN mms_seo_r2_stage s ON s.sku = TRIM(e.sku)
   SET v.value = s.md
 WHERE @ok AND v.attribute_id = @a_mdesc AND v.store_id = 0 AND v.value = s.old_md;

UPDATE catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id
  JOIN mms_seo_r2_stage s ON s.sku = TRIM(e.sku)
   SET t.value = s.mk
 WHERE @ok AND t.attribute_id = @a_mkey AND t.store_id = 0 AND t.value = s.old_mk;

DROP TABLE IF EXISTS mms_seo_r2_stage;

-- category 397 (name match tolerant of the double space)
SET @c397 := (SELECT COUNT(*) FROM catalog_category_entity_varchar
               WHERE entity_id = 397 AND attribute_id = @c_name AND store_id = 0
                 AND TRIM(REPLACE(value, '  ', ' ')) = 'WSQ Immersive AR Courses');
SET @ok397 := (@ok AND @c397 = 1);

SELECT 3, @c_mtitle, 0, 397, 'WSQ Immersive AR Courses in Singapore' FROM DUAL WHERE @ok397
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 3, @c_mdesc, 0, 397, 'Build augmented reality apps with AI vibe coding and explore business innovation with the metaverse and immersive tech. For creators. Up to 70% WSQ funding.' FROM DUAL WHERE @ok397
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 3, @c_mkey, 0, 397, 'WSQ AR courses Singapore, augmented reality training, AI vibe coding for AR, immersive technologies course, metaverse for business, WSQ funded AR course' FROM DUAL WHERE @ok397
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE v FROM catalog_category_entity_varchar v WHERE @ok397 AND v.entity_id = 397 AND v.attribute_id = @c_mtitle AND v.store_id <> 0;

DELETE t FROM catalog_category_entity_text t WHERE @ok397 AND t.entity_id = 397 AND t.attribute_id IN (@c_mdesc, @c_mkey) AND t.store_id <> 0;

SET @has_flat := (SELECT COUNT(*) FROM information_schema.COLUMNS
                   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_category_flat_store_1'
                     AND COLUMN_NAME IN ('meta_title', 'meta_description', 'meta_keywords'));
SET @q := IF(@ok397 AND @has_flat = 3,
  CONCAT('UPDATE catalog_category_flat_store_1 SET meta_title = ', QUOTE('WSQ Immersive AR Courses in Singapore'), ', meta_description = ', QUOTE('Build augmented reality apps with AI vibe coding and explore business innovation with the metaverse and immersive tech. For creators. Up to 70% WSQ funding.'), ', meta_keywords = ', QUOTE('WSQ AR courses Singapore, augmented reality training, AI vibe coding for AR, immersive technologies course, metaverse for business, WSQ funded AR course'), ' WHERE entity_id = 397'),
  'DO 0');
PREPARE st FROM @q;
EXECUTE st;
DEALLOCATE PREPARE st;
